play:none;position:absolute;right:0;top:58px;width:290px;z-index:120;background:#fff;border:1px solid #dce6ef;border-radius:14px;padding:15px;box-shadow:0 18px 50px rgba(8,47,95,.2)}.mf-popup.open{display:block}.mf-paxrow{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #edf2f6}.mf-step{display:flex;align-items:center;gap:10px}.mf-step button{width:28px;height:28px;border-radius:50%;border:1px solid #ccd8e3;background:#fff}.mf-done{width:100%;margin-top:11px;border:0;border-radius:9px;background:#082f5f;color:#fff;padding:10px;font-weight:900}.mf-note{margin-top:13px;color:#71869a;font-size:10px}@media(max-width:700px){.mf-head{flex-direction:column;align-items:start}.mf-row{grid-template-columns:1fr}.mf-swap{display:none}.mf-submit{height:50px}}
