<script src="https://cdn.jsdelivr.net/npm/flatpickr"></script>
<script>
document.addEventListener('DOMContentLoaded',()=>{const tripType=document.getElementById('tripType'),returnBox=document.getElementById('returnBox'),returnDate=document.getElementById('returnDate');function setTrip(t){tripType.value=t;document.querySelectorAll('.mf-tab').forEach(b=>b.classList.toggle('active',b.dataset.trip===t));if(t==='oneway'){returnBox.style.display='none';returnDate.removeAttribute('required');returnDate.value=''}else{returnBox.style.display='';returnDate.setAttribute('required','required')}}document.querySelectorAll('.mf-tab').forEach(b=>b.onclick=()=>setTrip(b.dataset.trip));let rp=flatpickr('#returnDate',{dateFormat:'Y-m-d',altInput:true,altFormat:'D, d M Y',minDate:'today',disableMobile:true});flatpickr('#departure',{dateFormat:'Y-m-d',altInput:true,altFormat:'D, d M Y',minDate:'today',disableMobile:true,onChange:(d,s)=>{if(s)rp.set('minDate',s)}});
async function airportSearch(q){const r=await fetch('api/airports.php?q='+encodeURIComponent(q));if(!r.ok)return[];const j=await r.json();return Array.isArray(j.results)?j.results:[]}function setupAirport(inputId,hiddenId,listId){const input=document.getElementById(inputId),hidden=document.getElementById(hiddenId),list=document.getElementById(listId);let timer=null,seq=0;input.addEventListener('input',()=>{hidden.value='';clearTimeout(timer);const q=input.value.trim();if(q.length<2){list.classList.remove('open');list.innerHTML='';return}timer=setTimeout(async()=>{const my=++seq,rows=await airportSearch(q);if(my!==seq)return;list.innerHTML='';rows.forEach(a=>{const el=document.createElement('div');el.className='mf-airport';el.innerHTML='<strong>'+a.city+' ('+a.code+')</strong><small>'+a.airport+' · '+a.country+'</small>';el.onclick=()=>{input.value=a.label;hidden.value=a.code;list.classList.remove('open')};list.appendChild(el)});list.classList.toggle('open',rows.length>0)},180)});document.addEventListener('click',e=>{if(!input.parentElement.contains(e.target))list.classList.remove('open')})}setupAirport('originText','originCode','originList');setupAirport('destinationText','destinationCode','destinationList');swap.onclick=()=>{const ot=originText.value,oc=originCode.value;originText.value=destinationText.value;originCode.value=destinationCode.value;destinationText.value=ot;destinationCode.value=oc};const trigger=document.getElementById('trigger'),popup=document.getElementById('popup');trigger.onclick=e=>{if(!e.target.closest('.mf-step')&&!e.target.closest('select')&&e.target.id!=='done')popup.classList.add('open')};done.onclick=e=>{e.stopPropagation();popup.classList.remove('open')};document.addEventListener('click',e=>{if(!trigger.contains(e.target))popup.classList.remove('open')});const state={adult:1,child:0,infant:0};function sync(){state.adult=Math.max(1,Math.min(9,state.adult));state.child=Math.max(0,Math.min(8,state.child));state.infant=Math.max(0,Math.min(state.adult,state.infant));adultInput.value=state.adult;childInput.value=state.child;infantInput.value=state.infant;adultCount.textContent=state.adult;childCount.textContent=state.child;infantCount.textContent=state.infant;const n=state.adult+state.child+state.infant;travellerText.textContent=n+(n===1?' traveller':' travellers')}document.querySelectorAll('[data-pax]').forEach(b=>b.onclick=e=>{e.stopPropagation();state[b.dataset.pax]+=+b.dataset.d;sync()});cabin.onchange=()=>cabinText.textContent=cabin.options[cabin.selectedIndex].text;mfForm.onsubmit=e=>{if(!originCode.value||!destinationCode.value){e.preventDefault();alert('Please select both airports from the suggestions.')}};setTrip('round');sync()});
</script>
